            <script src="https://cdnjs.cloudflare.com/ajax/libs/plotly.js/2.34.0/plotly.min.js"></script>
        </head>
        <body>
            <dialog id="llm-report-dialog">
                <div id="llm-report-dialog-content">
                    <button id="llm-report-dialog-close-btn">&times;</button>
                    <!-- Result of creating and arranging custom HTML layout elements -->
                    <div id="llm-report-title">Equipment Insights Report</div>
                    <div class="llm-report-section">
                        <div class="llm-report-section-title">Equipment Distribution</div>
                        <div id="chart-container"></div>
                        <div class="report-description">
                            This chart visualizes the distribution of equipment names available in the database. It provides insights into the variety and count of distinct equipment.
                        </div>
                    </div>
                    <div class="llm-report-section">
                        <div class="llm-report-section-title">Key Observations</div>
                        <ul class="report-description">
                            <li>The database contains distinct equipment names with no duplicates.</li>
                            <li>This visualization helps identify equipment variety within the organization.</li>
                            <li>Further analysis could segment equipment based on groups or bays.</li>
                        </ul>
                    </div>
                    <div class="llm-report-section">
                        <div class="llm-report-section-title">Actionable Insights</div>
                        <div class="report-description">
                            Based on the equipment distribution, the following actions are recommended:
                            <ol>
                                <li>Audit equipment for completeness and accuracy in naming conventions.</li>
                                <li>Utilize equipment groups for better management and categorization.</li>
                                <li>Investigate underrepresented groups or bays for potential gaps in resources.</li>
                            </ol>
                        </div>
                    </div>
                </div>
            </dialog>
            <script type="module">
                import { queryResultDataObj } from "../js/llm/llmMart.js";
                import { simConn } from "../js/hub/hub.js";
                // Write each query as a separate element in the `queries` list.
                let queries = [
                    "SELECT DISTINCT NAME FROM equipment",
                    "SELECT DISTINCT TOOL_GROUP FROM equipment",
                    "SELECT DISTINCT BAY FROM equipment"
                ];
                await simConn.invoke("SendQueryResult", queries);

                // Custom visualization result
                // Function for generating the chart and its data
                function renderSimpleReport() {
                    // Generate a chart from the first query result.
                    const equipmentData = queryResultDataObj[0];
                    const names = equipmentData.map(row => row["NAME"]);

                    const chartData = [{
                        x: names,
                        y: Array(names.length).fill(1), // Set each count to 1 for this simple example.
                        type: 'bar',
                        marker: { color: 'rgba(0, 123, 255, 0.8)' },
                    }];

                    Plotly.newPlot('chart-container', chartData, {
                        title: 'Equipment Distribution',
                        xaxis: { title: 'Equipment Names' },
                        yaxis: { title: 'Count' },
                        plot_bgcolor: '#f9f9f9',
                        paper_bgcolor: '#ffffff',
                        font: { color: '#333' },
                    });
                }

                // Execute the function.
                renderSimpleReport();
            </script>
        </body>
        </html>
