        <!DOCTYPE html>
        <html>
        <head>
            <meta charset="utf-8" />
            <style>
                #llm-report-dialog {
                    width: 70%;
                    border: none;
                    border-radius: 8px;
                    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
                    overflow-y: auto;
                }

                #llm-report-dialog::backdrop {
                    background: rgba(0, 0, 0, 0.5);
                }

                #llm-report-dialog-content {
                    padding: 20px;
                    background-color: #ffffff;
                    border-radius: 8px;
                    position: relative;
                    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
                }

                #llm-report-dialog-close-btn {
                    position: absolute;
                    top: 15px;
                    right: 15px;
                    color: #999;
                    font-size: 24px;
                    font-weight: bold;
                    background: none;
                    border: none;
                    cursor: pointer;
                }

                #llm-report-dialog-close-btn:hover {
                    color: #e74c3c;
                }

                /* Custom styles for office-like feel */
                #llm-report-title {
                    text-align: center;
                    font-size: 28px;
                    font-weight: bold;
                    margin-bottom: 30px;
                    color: #2c3e50;
                    border-bottom: 2px solid #bdc3c7;
                    padding-bottom: 10px;
                }

                .section {
                    margin-bottom: 30px;
                }

                .section-title {
                    font-size: 20px;
                    color: #34495e;
                    margin-bottom: 15px;
                    border-left: 4px solid #2980b9;
                    padding-left: 10px;
                }

                .description {
                    font-size: 15px;
                    color: #7f8c8d;
                    line-height: 1.6;
                    margin-top: 10px;
                }

                #utilization-chart {
                    width: 100%;
                    height: 400px;
                    margin-top: 20px;
                    background-color: #ecf0f1;
                    border: 1px solid #bdc3c7;
                    border-radius: 8px;
                    padding: 10px;
                }

                .data-table {
                    width: 100%;
                    border-collapse: collapse;
                    margin-top: 20px;
                    font-size: 14px;
                }

                .data-table th, .data-table td {
                    border: 1px solid #dfe6e9;
                    padding: 8px;
                    text-align: center;
                }

                .data-table th {
                    background-color: #dfe6e9;
                    color: #2d3436;
                }
            </style>
            <script src="https://cdnjs.cloudflare.com/ajax/libs/plotly.js/2.34.0/plotly.min.js"></script>
        </head>
        <body>
            <dialog id="llm-report-dialog">
                <div id="llm-report-dialog-content">
                    <button id="llm-report-dialog-close-btn">&times;</button>
                    <div id="llm-report-title">Equipment Utilization Report</div>
                    <div class="section">
                        <div class="section-title">Overall Utilization</div>
                        <div id="utilization-chart"></div>
                        <div class="description">
                            The chart illustrates the utilization rates of different equipment over the selected period. This helps in identifying underutilized or overutilized assets.
                        </div>
                    </div>
                    <div class="section">
                        <div class="section-title">Detailed Utilization Data</div>
                        <table class="data-table">
                            <thead>
                                <tr>
                                    <th>Equipment Name</th>
                                    <th>Operating Time (hrs)</th>
                                    <th>Total Time (hrs)</th>
                                    <th>Utilization Rate (%)</th>
                                </tr>
                            </thead>
                            <tbody id="utilization-table-body">
                                <!-- Table rows will be inserted here -->
                            </tbody>
                        </table>
                    </div>
                </div>
            </dialog>
            <script type="module">
                import { queryResultDataObj } from "../js/llm/llmMart.js";
                import { simConn } from "../js/hub/hub.js";

                // SQL queries to fetch utilization data
                let queries = [
                    `SELECT EQP_NAME,
                            SUM(TIMESTAMPDIFF(MINUTE, PROCESS_START_TIME, PROCESS_FINISH_TIME))/60 AS OPERATING_TIME,
                            24 AS TOTAL_TIME,
                            (SUM(TIMESTAMPDIFF(MINUTE, PROCESS_START_TIME, PROCESS_FINISH_TIME))/(24*60))*100 AS UTILIZATION_RATE
                     FROM eqpsteplog
                     GROUP BY EQP_NAME`
                ];

                await simConn.invoke("SendQueryResult", queries);

                // Render the utilization chart
                function renderUtilizationChart() {
                    const data = queryResultDataObj[0];
                    const eqpNames = data.map(row => row["EQP_NAME"]);
                    const utilizationRates = data.map(row => row["UTILIZATION_RATE"]);

                    const chartData = [{
                        x: eqpNames,
                        y: utilizationRates,
                        type: 'bar',
                        marker: { color: '#3498db' },
                    }];

                    Plotly.newPlot('utilization-chart', chartData, {
                        title: 'Equipment Utilization Rates',
                        xaxis: { title: 'Equipment Name' },
                        yaxis: { title: 'Utilization Rate (%)' },
                        plot_bgcolor: '#f5f5f5',
                        paper_bgcolor: '#ffffff',
                        font: { color: '#2c3e50' },
                    });
                }

                // Render the utilization table
                function renderUtilizationTable() {
                    const data = queryResultDataObj[0];
                    const tableBody = document.getElementById('utilization-table-body');

                    data.forEach(row => {
                        const tr = document.createElement('tr');
                        tr.innerHTML = `
                            <td>${row["EQP_NAME"]}</td>
                            <td>${parseFloat(row["OPERATING_TIME"]).toFixed(2)}</td>
                            <td>${row["TOTAL_TIME"]}</td>
                            <td>${parseFloat(row["UTILIZATION_RATE"]).toFixed(2)}%</td>
                        `;
                        tableBody.appendChild(tr);
                    });
                }

                // Execute the functions
                renderUtilizationChart();
                renderUtilizationTable();
            </script>
        </body>
        </html>
        '''


        '''
