            </dialog>
            <script type="module">
                import { queryResultDataObj } from "../js/llm/llmMart.js";
                import { simConn } from "../js/hub/hub.js";

                // SQL queries to fetch KPI data
                let queries = [
                    `SELECT COUNT(DISTINCT LOT_NAME) AS TOTAL_LOTS FROM eqpsteplog`,
                    `SELECT AVG(TIMESTAMPDIFF(HOUR, PROCESS_START_TIME, PROCESS_FINISH_TIME)) AS AVERAGE_CYCLE_TIME FROM eqpsteplog`,
                    `SELECT (SUM(CASE WHEN IS_BREACH = 0 THEN 1 ELSE 0 END)/COUNT(*))*100 AS YIELD_PERCENTAGE FROM queuetimelog`,
                    `SELECT DATE(PROCESS_FINISH_TIME) AS DATE, COUNT(DISTINCT LOT_NAME) AS LOTS_PROCESSED
                     FROM eqpsteplog
                     GROUP BY DATE(PROCESS_FINISH_TIME)
                     ORDER BY DATE(PROCESS_FINISH_TIME)`
                ];

                await simConn.invoke("SendQueryResult", queries);

                // Display KPI values
                function displayKPIValues() {
                    const totalLots = queryResultDataObj[0][0]["TOTAL_LOTS"];
                    const averageCycleTime = parseFloat(queryResultDataObj[1][0]["AVERAGE_CYCLE_TIME"]).toFixed(2);
                    const yieldPercentage = parseFloat(queryResultDataObj[2][0]["YIELD_PERCENTAGE"]).toFixed(2);

                    document.getElementById('total-lots').innerText = totalLots;
                    document.getElementById('average-cycle-time').innerText = averageCycleTime;
                    document.getElementById('yield-percentage').innerText = yieldPercentage + '%';
                }

                // Render the production chart
                function renderProductionChart() {
                    const data = queryResultDataObj[3];
                    const dates = data.map(row => row["DATE"]);
                    const lotsProcessed = data.map(row => row["LOTS_PROCESSED"]);

                    const chartData = [{
                        x: dates,
                        y: lotsProcessed,
                        type: 'scatter',
                        mode: 'lines+markers',
                        line: { color: '#27ae60' },
                        marker: { color: '#27ae60' },
                    }];

                    Plotly.newPlot('production-chart', chartData, {
                        title: 'Lots Processed Over Time',
                        xaxis: { title: 'Date' },
                        yaxis: { title: 'Lots Processed' },
                        plot_bgcolor: '#ffffff',
                        paper_bgcolor: '#ffffff',
                        font: { color: '#333333' },
                    });
                }

                // Execute the functions
                displayKPIValues();
                renderProductionChart();
            </script>
        </body>
        </html>
        '''
